function prng(seed){var a=(seed>>>0)||1;return function(){a|=0;a=(a+0x6D2B79F5)|0;var t=Math.imul(a^(a>>>15),1|a);t=(t+Math.imul(t^(t>>>7),61|t))^t;return((t^(t>>>14))>>>0)/4294967296;};}
function demoRun(seed){var R=prng(seed*999983+29);var req=['ingest','index','search','rank','explain','audit','generate','verify','route','cache','alert','export'];var avail=req.filter(function(){return R()<0.55;});var gaps=req.filter(function(x){return avail.indexOf(x)<0;});var proposed=gaps.slice(0,Math.ceil(gaps.length/2)).map(function(x){return'stub-'+x;});return{required:req.length,available:avail.length,gaps:gaps,coverage_before_pct:+(100*avail.length/req.length).toFixed(1),proposed_tools:proposed,coverage_after_pct:+(100*(avail.length+proposed.length)/req.length).toFixed(1)};}
var SEED = 85501;
console.log(JSON.stringify(demoRun(SEED), null, 1));

